func pinnedEnsureRequest(state MemberState) oci.EnsureRequest {
	privateIP, _, _ := net.SplitHostPort(state.RuntimeManifest.ReplicationListenAddress)
	// The fleet rejects an empty name, so an unnamed seat fails closed there.
	name, _ := seatMemberName(state.Region, state.MemberID)
	return oci.EnsureRequest{
		Name: name, CreateKey: state.CreateKey, PrivateIP: privateIP, FaultDomain: state.FailureDomain,
		Shape: state.ManagedHostProfile.Compute.Shape, WholeOCPUs: state.ManagedHostProfile.Compute.WholeOCPUs,
		MemoryInGBs:            state.ManagedHostProfile.Compute.MemoryInGBs,
		PlacementProfileDigest: state.ManagedHostProfileDigest, PlacementGeneration: state.IntentGeneration,
		BootPins: oci.HostBootPins{
			DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
			HostAttempt: state.HostAttempt, IntentPayloadDigest: state.IntentPayloadDigest,
			CanonicalRosterDigest: state.CanonicalRosterDigest, RuntimeManifestDigest: state.RuntimeManifestDigest,
		},
	}
}

identity.text:
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

