func ValidateManagedRegistrationPins(registration Registration, pins ManagedRegistrationPins) error {
	if registration.ManagedPlacement == nil || *registration.ManagedPlacement != pins.Placement ||
		registration.ManagedMember == nil || *registration.ManagedMember != pins.Member ||
		registration.ManagedOCI == nil || *registration.ManagedOCI != pins.OCI ||
		registration.FailureDomain != pins.FailureDomain || pins.AllocatableMemoryBytes > math.MaxInt64 ||
		registration.Capacity.MemoryBytes != int64(pins.AllocatableMemoryBytes) || pins.SystemReserveBytes > math.MaxInt64 ||
		registration.SystemReserveBytes != int64(pins.SystemReserveBytes) {
		return errors.New("managed registration differs from current placement pins")
	}
	return nil
}

func validateManagedMemberBinding(binding ManagedMemberBinding) error {
	scope := binding.Scope
	if !lowerHexIdentity(scope.ClusterID) || !lowerHexIdentity(scope.Incarnation) ||
		!canonicalMemberID(scope.TenantID) || !canonicalMemberID(scope.DatabaseID) ||
		!canonicalMemberID(scope.MemberID) || scope.ShardID == 0 || binding.HostAttempt == 0 {
		return errors.New("managed member identity is invalid")
	}
	return nil
}

mount_path.text:
func ManagedMountPath(root string, member ManagedMemberBinding) (string, error) {
	paths, err := runtimePaths(root, ManagedMemberLaunch{Member: member})
	if err != nil {
		return "", err
	}
	return paths.mount, nil
}

runtime_paths.text:
func runtimePaths(root string, launch ManagedMemberLaunch) (managedRuntimePaths, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == "/" {
		return managedRuntimePaths{}, errors.New("managed runtime root must be a clean absolute directory")
	}
	scope := launch.Member.Scope
	if err := validateManagedMemberBinding(launch.Member); err != nil {
		return managedRuntimePaths{}, err
	}
	sum := sha256.Sum256([]byte(scope.ClusterID + "/" + scope.TenantID + "/" + scope.DatabaseID + "/" +
		strconv.FormatUint(scope.ShardID, 10) + "/" + scope.MemberID + "/" + scope.Incarnation + "/" +
		strconv.FormatUint(launch.Member.HostAttempt, 10)))
	memberDir := filepath.Join(root, hex.EncodeToString(sum[:16]))
	paths := managedRuntimePaths{
		memberDir:  memberDir,
		mount:      filepath.Join(memberDir, "volume"),
		material:   filepath.Join(memberDir, "material"),
		socket:     filepath.Join(memberDir, "control", "member.sock"),
		nativeRoot: filepath.Join(memberDir, "native-root.sock"),
	}
	if len(paths.socket) >= 108 || len(paths.nativeRoot) >= 108 {
		return managedRuntimePaths{}, errors.New("managed socket path exceeds Unix limit")
	}
	return paths, nil
}

proof_identity.text:
func (s Scope) valid() bool {
	return lowerHexIdentity(s.ClusterID) && lowerHexIdentity(s.Incarnation) && s.ShardID != 0 &&
		canonicalID(s.TenantID) && canonicalID(s.DatabaseID) && canonicalID(s.MemberID)
}

func (a Authority) valid() bool {
	return a.Epoch != 0 && lowerHex(a.ConfigurationID, 64) &&
		lowerHex(a.CertificateSHA256, 64) && lowerHex(a.TLSLeafSHA256, 64)
}

func (p Process) valid() bool { return p.PID >= 1 && lowerHex(p.StartNonce, 32) }

func (s Survivor) valid() bool {
	return canonicalID(s.MemberID) && lowerHexIdentity(s.Incarnation)
}

protocol_json.text:
func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

